import {config,gameId,groups,clone,isDone,count,nextStep,edit,undoEdit,envelope,importData,differences,applyDifferences,trophyCondition} from './model.js';
const source=import.meta.url.includes('/dist/');
const {createStore}=await import(new URL(source?'../../../shared/roadmap-store.js':'../../shared/roadmap-store.js',import.meta.url));
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={roadmap:'冒險路線 Roadmap',collections:'收藏與查漏',trophies:'PS5 獎盃',advice:'建議攻略',backup:'資料管理／來源'};
const cats={mm:'小徽章',fm:'友善魔物',enemy:'討伐圖鑑',skills:'咒文與特技',counters:'遊戲計數',supplies:'試煉備料',arena:'怪物競技場',wishes:'Xenlon 七願',rewards:'徽章兌獎'};
let data,progress,ready=false,busy=false,refreshPending=false,review,lastUndo,retry,search='',status='pending',category='mm',region='',vocation='',trophyType='',target='';
const peeks=new Set();
const params=()=>new URL(location.href).searchParams;
const view=()=>Object.hasOwn(names,params().get('view'))?params().get('view'):'roadmap';
const phase=()=>data.phases.some(p=>p.id===params().get('phase'))?params().get('phase'):(data.phases.some(p=>p.id===progress.settings.phase?.value)?progress.settings.phase.value:'phase-1');
const message=s=>$('feedback').textContent=s;
const store=createStore(config,{clone},()=>{if(!ready)return;if(busy){refreshPending=true;return;}refresh().catch(e=>message('更新失敗：'+e.message));});
function drainUpdates(){if(refreshPending){refreshPending=false;refresh().catch(e=>message('更新失敗：'+e.message));}}
async function refresh(){progress=await store.get();if(review&&JSON.stringify(progress)!==review.stamp){review.expired=true;$('import-status').textContent='預覽已過期，請取消後重新比較。';gate();}render(true);}
function inline(text){return esc(text).replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdown(text){const lines=text.split('\n');let result='',table=[];const flush=()=>{if(!table.length)return;const headers=table[0];result+='<table><thead><tr>'+headers.map(h=>'<th>'+inline(h)+'</th>').join('')+'</tr></thead><tbody>'+table.slice(1).filter(r=>!r.every(c=>/^[-: ]+$/.test(c))).map(r=>'<tr>'+r.map((c,i)=>'<td data-label="'+esc(headers[i])+'">'+inline(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';table=[];};for(const l of lines){if(l.trim().startsWith('|')){table.push(l.trim().slice(1,-1).split('|').map(s=>s.trim()));continue;}flush();if(!l.trim())continue;if(/^#{1,4} /.test(l))result+='<h3>'+inline(l.replace(/^#+ /,''))+'</h3>';else result+='<p>'+inline(l.replace(/^\s*- /,''))+'</p>';}flush();return result;}
const href=(v,extra={})=>'?'+new URLSearchParams({view:v,...extra});
const link=(v,label,extra={})=>`<a href="${esc(href(v,extra))}" data-route>${esc(label)}</a>`;
const date=n=>n?new Date(n).toLocaleString('zh-TW',{hour12:false}):'尚未核對';
const checked=(g,id)=>isDone(progress,g,id)?'checked':'';
function check(g,id,label){return `<label class="check"><input type="checkbox" id="${esc(g+'-'+id)}" data-group="${g}" data-id="${esc(id)}" ${checked(g,id)}><span class="row-title">${esc(label)}</span></label>`;}
function options(rows,value){return rows.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');}
function match(row,g){return (status==='all'||isDone(progress,g,row.id)===(status==='done'))&&(!search||searchText(row).includes(searchText(search)))&&(!target||row.id===target);}
function searchText(value){return (typeof value==='string'?value:JSON.stringify(value)).toLowerCase().replace(/’/g,"'").replace(/immigrant town/g,'merchantburg').replace(/shallows? shrine/g,'shallows shrine').replace(/馴獸師|魔物使|魔物大師/g,'monster wrangler').replace(/北西/g,'西北').replace(/北東/g,'東北');}
function toolbar(extra=''){return `<div class="toolbar"><label class="search">搜尋名稱、地點、別名或 ID<input type="search" id="search" value="${esc(search)}" placeholder="例如 Romaria、mm-001"></label>${extra}<label>顯示狀態<select id="status">${options([['pending','未完成／未取得'],['all','全部'],['done','已完成／已取得']],status)}</select></label><button data-reset>重設條件</button></div>`;}
const empty=()=>`<p class="empty">${search?'搜尋無符合項目':status==='pending'?'此區已查完，或目前條件沒有未完成項目':'目前條件沒有項目'}。<button data-reset>重設篩選</button></p>`;
function stats(){return `<div class="stats">${link('trophies',`${count(progress,'trophies',data.trophies)} / 42 已確認獎盃`)}${['mm','fm','enemy'].map(c=>{const rows=data.collectibles.filter(x=>x.category===c);return link('collections',`${cats[c]} ${count(progress,'collectibles',rows)} / ${rows.length}`,{category:c});}).join('')}${link('collections',`技能 ${count(progress,'skills',data.skills)} / 135`,{category:'skills'})}</div>`;}
function stepLink(id,label='回到取得路線'){const s=data.steps.find(s=>s.id===id);return s?link('roadmap',label,{phase:s.phaseId,target:id}):'';}
function collectRow(r){return `<article class="row" id="entry-${esc(r.id)}">${check('collectibles',r.id,r.name)}<div class="row-body"><small>${esc(r.id)} · ${esc(r.region)} · ${esc(r.location)}</small><p>${inline(r.actions)}</p>${r.category==='fm'?'<p class="requirement">時段／前置：'+esc(r.conditions)+'</p>':''}<div class="inline-links">${stepLink(r.firstPracticalStepId)}${link('collections','在清單查看',{category:r.category,target:r.id})}</div></div></article>`;}
function objectiveRow(o){return `<article class="row" id="entry-${esc(o.id)}">${check('objectives',o.id,o.label)}${o.id==='wish-book-final'&&count(progress,'objectives',data.wishes.filter(w=>w.id!==o.id))<6?'<p class="requirement">先許完其他六個不同願望。</p>':''}</article>`;}
function trophyRow(t,embedded=false){const c=trophyCondition(progress,t,data);return `<article class="row" id="entry-${t.id}">${check('trophies',t.id,t.label)}<div class="row-body"><small>${t.id} · ${esc(t.grade)} · ${esc(t.category)}${t.hidden?' · 隱藏盃':''}</small><p>${inline(t.actions)}</p>${c?`<p data-condition="${t.id}">${c.met?'站內條件已滿足，待確認跳盃':'本站核對'} ${c.done} / ${c.total}${t.id==='tr-25'?'（110 地點＋最終兌獎）':''}</p>`:''}<div class="inline-links">${stepLink(t.stepId)}${embedded?link('trophies','查看獎盃',{target:t.id}):''}${trophyMissingLinks(t)}</div></div></article>`;}
function trophyMissingLinks(t){const category={'tr-19':'enemy','tr-20':'counters','tr-21':'skills','tr-23':'wishes','tr-24':'fm','tr-25':'mm','tr-26':'arena','tr-27':'counters','tr-28':'counters','tr-29':'counters','tr-30':'counters','tr-31':'counters'}[t.id];return category?link('collections','查看對應缺項',{category}):'';}
function readingUnit(){const rows=data.readingUnits.filter(u=>u.phaseId===phase()),step=data.steps.find(s=>s.id===target);return rows.find(u=>u.id===params().get('unit'))||rows.find(u=>step&&step.order>=u.start&&step.order<=u.end)||rows[0];}
function road(){const pid=phase(),unit=readingUnit(),rows=data.steps.filter(s=>s.phaseId===pid&&s.order>=unit.start&&s.order<=unit.end),n=nextStep(progress,data);return `<div class="page-heading"><div><h1>冒險路線</h1><p class="muted">${n?'下一個主線動作：'+esc(n.label):'主線已勾完，可繼續破關後與收藏查漏。'}</p></div><button class="primary" id="continue">${n&&n.phaseId==='phase-4'?'繼續破關後':'繼續遊玩'}</button></div><div class="road-stats">${stats()}</div><label class="phase-picker">遊玩階段<select id="phase-select">${options(data.phases.map(p=>[p.id,p.label]),pid)}</select></label><nav class="phases" aria-label="遊玩階段">${data.phases.map(p=>`<button data-phase="${p.id}" aria-pressed="${p.id===pid}">${esc(p.label)}<small>${count(progress,'steps',data.steps.filter(s=>s.phaseId===p.id))} / ${data.steps.filter(s=>s.phaseId===p.id).length} 步驟完成</small></button>`).join('')}</nav><div class="actions"><label>行進段落<select id="reading-unit">${options(data.readingUnits.filter(u=>u.phaseId===pid).map(u=>[u.id,u.label]),unit.id)}</select></label><button id="save-bookmark">將目前章節設為書籤</button></div><p class="summary-line">自由閱讀不改進度；續玩依實際主線勾選定位。</p>${pid==='phase-2'?`<h2>六寶珠進度</h2><div class="orb-strip">${[[15,'綠'],[16,'紅'],[17,'藍'],[18,'紫'],[21,'黃'],[23,'銀']].map(([n,label])=>{const s=data.steps[n-1];return `<a class="${isDone(progress,'steps',s.id)?'obtained':''}" data-route href="${href('roadmap',{phase:pid,target:s.id})}">${label}珠 · ${isDone(progress,'steps',s.id)?'已確認':'未確認'}</a>`;}).join('')}</div>`:''}<details class="road-filters"><summary>搜尋與顯示條件</summary>${toolbar()}</details>${rows.filter(r=>match(r,'steps')).map(step).join('')||empty()}`;}
function step(s){const done=isDone(progress,'steps',s.id),expanded=!done||peeks.has(s.id),missing=s.requirements.filter(id=>!isDone(progress,'steps',id));const items=data.collectibles.filter(r=>r.firstPracticalStepId===s.id),objectives=data.objectives.filter(r=>r.stepId===s.id),trophies=data.trophies.filter(t=>t.stepId===s.id);
 const grouped=Map.groupBy(items,r=>r.locationId);
 return `<article class="row step ${done?'done':''}" id="entry-${s.id}"><div class="step-heading">${check('steps',s.id,s.label)}<button data-peek="${s.id}" ${done?'':'hidden'}>${expanded?'收合':'回看'}</button></div><small>${s.id} · ${s.requiredForRoute?'主線':'白金支線／可選回訪'}</small>${s.warnings.map(w=>'<div class="warning">'+inline(w)+'</div>').join('')}<div class="row-body" id="body-${s.id}" ${expanded?'':'hidden'}>${missing.length?'<p class="requirement">建議前置：'+missing.map(id=>stepLink(id,data.steps.find(s=>s.id===id).label)).join('、')+'（可自由瀏覽與補登）</p>':''}<h3>現在去哪、照做</h3><p>${inline(s.actions)}</p><h3>完成檢查／離開前</h3><p>${inline(s.doneWhen)}</p>${s.returnIds?.some(id=>!isDone(progress,'collectibles',id))?'<h3>回來再做</h3>'+s.returnIds.filter(id=>!isDone(progress,'collectibles',id)).map(id=>{const r=data.collectibles.find(x=>x.id===id);return '<p>'+esc(r.name+' · '+r.location+'｜'+r.conditions)+' '+stepLink(r.firstPracticalStepId,'前往回收階段')+'</p>';}).join(''):''}${s.order===34?'<p>已許 '+count(progress,'objectives',data.wishes)+' / 7 個不同願望。下一願合格門檻 '+(count(progress,'objectives',data.wishes)===0?35:count(progress,'objectives',data.wishes)===1?25:15)+' 回合內。</p>':''}${s.order===36?'<p>已確認 '+count(progress,'objectives',data.trials)+' / 5 座火台。'+(count(progress,'objectives',data.trials)===5?'北門已具備開啟條件，先收 Xenwrong，再分檔挑戰 Grand Dragon。':'依下方各側需求核對，尚未全亮先補缺項。')+'</p>':''}${s.navigation?markdown(s.navigation):''}${objectives.length?'<h3>個別確認</h3>'+objectives.map(objectiveRow).join(''):''}${s.order===36?'<p>'+link('collections','盤點西側七類供品',{category:'supplies'})+'</p>':''}${s.order===34?'<p>'+link('advice','Xenlon 與試煉戰法',{section:'advice-4'})+'</p>':''}${items.length?'<h3>沿路收藏與回收</h3>'+[...grouped].map(([,rs])=>'<section><h3>'+esc(rs[0].location)+'</h3>'+rs.filter(r=>!isDone(progress,'collectibles',r.id)).map(collectRow).join('')+(!rs.some(r=>!isDone(progress,'collectibles',r.id))?'<small>此地已核對完成。</small>':'')+'</section>').join(''):''}${trophies.length?'<h3>PS5 跳盃確認</h3>'+trophies.map(t=>trophyRow(t,true)).join(''):''}</div></article>`;
}
function collections(){let content='';const list=['mm','fm','enemy'].includes(category)?data.collectibles.filter(r=>r.category===category):[];
 const extra=list.length?`<label>區域<select id="region">${options([['','全部區域'],...[...new Set(list.map(r=>r.region))].map(v=>[v,v])],region)}</select></label>`:category==='skills'?`<label>職系<select id="vocation">${options([['','全部職系'],...[...new Set(data.skills.flatMap(s=>s.vocations))].map(v=>[v,v])],vocation)}</select></label>`:'';
 if(list.length)content=list.filter(r=>match(r,'collectibles')&&(!region||r.region===region)).map(collectRow).join('');
 if(category==='skills')content=data.skills.filter(r=>match(r,'skills')&&(!vocation||r.vocations.includes(vocation))).map(s=>`<article class="row" id="entry-${esc(s.id)}">${check('skills',s.id,s.name)}<div class="row-body"><small>${s.kind==='spell'?'咒文':'特技'} · ${esc(s.vocations.join('／'))} · ${esc(s.id)}</small><p>${esc([...new Set(s.notes)].join(' '))}</p>${stepLink(s.firstPracticalStepId,'轉職與職系規劃')}</div></article>`).join('');
 if(category==='counters')content=`<p>依遊戲 Misc. → Info 手動核對；超過門檻可照實輸入，不從收藏勾選累加。</p>${data.counters.filter(r=>searchText(r).includes(searchText(search))).map(c=>`<div class="counter"><label for="counter-${c.id}">${esc(c.label)}<small>獎盃門檻 ${c.target.toLocaleString()} · ${date(progress.counters[c.id]?.updatedAt)}</small></label><input type="number" min="0" step="1" id="counter-${c.id}" data-counter="${c.id}" value="${progress.counters[c.id]?.value||0}"><button data-save-counter="${c.id}">更新計數</button></div>`).join('')}<h2>還差數量時怎麼補</h2>${markdown(data.counterGuidance)}`;
 if(category==='supplies')content=`<div class="warning">交付與在手數量分開記錄，交付後不扣改網站數量。依缺額估算剩餘金額，不推測遊戲庫存。</div>${data.supplies.filter(r=>match(r,'supplies')).map(s=>{const row=progress.supplies[s.id]||{},short=row.done?0:Math.max(0,s.required-(row.quantity||0));return `<article class="row" id="entry-${s.id}">${check('supplies',s.id,s.name+'｜已交付')}<p>${esc(s.shop)} · 單價 ${s.price.toLocaleString()} G · 需 ${s.required}，尚缺 ${short}</p><div class="supply-controls"><label>在手數量 <input type="number" min="0" step="1" id="quantity-${s.id}" value="${row.quantity||0}"></label><button data-save-supply="${s.id}">更新備料</button></div></article>`;}).join('')}<p>未交付採買缺額：${data.supplies.reduce((sum,s)=>sum+(isDone(progress,'supplies',s.id)?0:Math.max(0,s.required-(progress.supplies[s.id]?.quantity||0))*s.price),0).toLocaleString()} G（全額 615,000 G）</p>${stepLink(data.steps[35].id)}`;
 if(['arena','wishes','rewards'].includes(category)){const rows=category==='arena'?data.arena:category==='wishes'?data.wishes:data.rewards;content=rows.filter(r=>match(r,'objectives')).map(r=>{const o=data.objectives.find(o=>o.id===r.id);return objectiveRow(o)+(category==='arena'?`<p>入場 ${esc(r.fee)} · 首通獎金 ${esc(r.prize)}<br>${esc(r.reward)}</p>`:'');}).join('');}
 const medals=count(progress,'collectibles',data.collectibles.filter(r=>r.category==='mm')),reward=data.rewards.find(r=>r.target>medals);
 return `<h1>收藏與查漏</h1><div class="collection-stats">${stats()}</div><label class="category-picker">查漏類別<select id="category-select">${options(Object.entries(cats),category)}</select></label><div class="tabs collection-tabs" aria-label="收藏分類">${Object.entries(cats).map(([c,label])=>`<button data-category="${c}" aria-pressed="${c===category}">${label}</button>`).join('')}</div><h2>${cats[category]}${list.length?` · ${count(progress,'collectibles',list)} / ${list.length}`:''}</h2>${category==='mm'?'<p>已核對 '+medals+' / 110 個地點。'+(reward?'下一個獎勵：'+reward.target+' 枚 '+esc(reward.name):'已收齊地點，請核對最終兌獎。')+' '+link('collections','兌獎清單',{category:'rewards'})+'</p>':''}${category==='fm'?'<p>按地點＋物種核對，綽號搜尋會列出同種候選。帶 Monster Wrangler 仍須滿足各列條件；找不到時用 Animal Instinct。</p>':''}${category==='skills'?'<p>135 種共享紀錄（66 咒文、69 特技）；跨職同招只計一次。以實機 ??? 是否消失為準，等級僅為規劃參考。</p>':''}${toolbar(extra)}${content||empty()}`;
}
function trophies(){return `<h1>PS5 獎盃</h1><p class="muted">${count(progress,'trophies',data.trophies)} / 42 已確認 · 1 白金、4 金、6 銀、31 銅 · NPWR42614_00</p><p>在 PS5 確認已跳盃後才勾選。站內達標提示不代替實際獎盃。</p>${toolbar(`<label>類別<select id="trophy-type">${options([['','全部類別'],...['主線','條件','收藏','通關後'].map(v=>[v,v])],trophyType)}</select></label>`)}${data.trophies.filter(t=>match(t,'trophies')&&(!trophyType||t.category===trophyType)).map(t=>trophyRow(t)).join('')||empty()}`;}
function advice(){const n=nextStep(progress,data);return `<h1>建議攻略</h1><p class="muted">${n?'目前主線待辦：'+esc(n.label):'主線完成，建議依收藏與技能缺項補強。'}</p><nav class="read-index">${data.advice.map(s=>`<a href="#${s.id}">${esc(s.title)}</a>`).join('')}</nav><div class="inline-links">${link('collections','核對逐招技能',{category:'skills'})}${link('collections','試煉備料',{category:'supplies'})}${link('collections','競技場紀錄',{category:'arena'})}${stepLink(data.steps[11].id,'轉職路線')}${stepLink(data.steps[36].id,'Grand Dragon 戰前檢查')}</div>${data.advice.map(s=>`<section class="advice-section" id="${s.id}"><h2>${esc(s.title)}</h2>${markdown(s.markdown)}</section>`).join('')}`;}
function backup(){return `<h1>資料管理／來源</h1><h2>備份與還原</h2><p>此瀏覽器已保存修訂 ${progress.revision} · ${date(progress.updatedAt)}。換瀏覽器、清除網站資料或換連接埠前，請先下載 JSON。</p><div class="actions"><button id="export-progress">下載進度 JSON</button><button id="export-all">下載完整復原封存</button></div><p><label>匯入本遊戲 JSON（最大 10 MB）<input type="file" id="import-file" accept=".json,application/json"></label></p><p>檔案會先封存兩端原文，顯示逐筆差異，下載復原備份並確認後才套用。取消不改進度；來源缺項不刪除本機項目。此檔案不是 PS5 遊戲存檔。</p><h2>版本與覆蓋</h2><p>PS5 1.1.1.0 · 資料 ${esc(data.dataVersion)} · 38 步驟、42 獎盃、110 徽章、121 收服點、163 討伐、135 招技能、11 競技級別。源自使用者提供的規格。</p><div class="warning">未於 PS5 逐點、逐技能與逐盃實測。未知繁中名稱保留英文，綽號不作身分鍵。Grand Dragon 採安全目標 20 回合內；21–25 回合來源分歧請直接核對 Grand Medal。</div><h2>路線與回收規則</h2><details><summary>閱讀錨點、回收與試煉導航</summary>${markdown(data.routeGuidance)}</details><h2>查證來源</h2><p>規格記錄查閱日：2026-11-23。外連用於查證，主要操作不需網路。</p>${data.sources.filter((s,i,a)=>a.findIndex(x=>x.url===s.url)===i).map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></p>`).join('')}`;}
function render(preserve=false){if(!ready)return;const filtersOpen=document.querySelector('.road-filters')?.open;const active=document.activeElement,focusId=active?.id,selection=active?.tagName==='INPUT'&&active.type==='search'?[active.selectionStart,active.selectionEnd]:null;
 const y=scrollY,rows=[...document.querySelectorAll('main .row')],anchor=rows.find(r=>r.getBoundingClientRect().top>=0),anchorId=anchor?.id,top=anchor?.getBoundingClientRect().top,scrolls=rows.filter(r=>r.id).map(r=>({id:r.id,y:r.getBoundingClientRect().top}));
 const controls=[...document.querySelectorAll('main input,main button,main select')],index=controls.indexOf(active);
 $('main').innerHTML=({roadmap:road,collections,trophies,advice,backup}[view()])();
 const filters=document.querySelector('.road-filters');if(filters)filters.open=preserve?!!filtersOpen:matchMedia('(min-width:721px)').matches;
 document.querySelectorAll('[data-view]').forEach(a=>a.setAttribute('aria-current',a.dataset.view===view()?'page':'false'));
 if(target){const element=$('entry-'+target);if(element)element.classList.add('target');$('main').insertAdjacentHTML('afterbegin','<p class="summary-line">正在定位：'+esc(target)+' <button data-reset>清除定位</button></p>');}
 if(preserve){let node=focusId?$(focusId):null;if(!node&&index>=0){const id=active?.dataset.id;const row=scrolls.findIndex(r=>r.id==='entry-'+id);for(const candidate of scrolls.slice(row+1)){const found=$(candidate.id);if(found){node=found.querySelector('input,button,a');break;}}node||=$('main');}node?.focus({preventScroll:true});if(selection&&node?.type==='search')node.setSelectionRange(...selection);const same=anchorId&&$(anchorId);if(same)scrollTo(0,y+same.getBoundingClientRect().top-top);else scrollTo(0,y);}
}
function reset(){search='';status=view()==='roadmap'?'all':'pending';region='';vocation='';trophyType='';target='';}
function navigate(v,extra={}){history.pushState({},'',href(v,extra));reset();category=Object.hasOwn(cats,extra.category)?extra.category:'mm';target=extra.target||'';if(target)status='all';render();if(matchMedia('(max-width:720px)').matches)$('menu').open=false;requestAnimationFrame(()=>{const t=target?$('entry-'+target):extra.section?$(extra.section):null;if(t){t.scrollIntoView({block:'start'});(t.querySelector('input,button')||t).focus({preventScroll:true});}else{scrollTo(0,0);$('main').focus({preventScroll:true});}});}
async function save(g,id,value){if(busy)return;busy=true;retry=()=>save(g,id,value);try{const result=await edit(store,g,id,value);progress=result.progress;lastUndo=result.undo;$('undo').hidden=false;$('retry').hidden=true;retry=null;message('已保存，可撤銷這一筆。');if(review)review.expired=true;render(true);}catch(e){message('保存失敗：'+e.message+'；原資料保留，請重試。');$('retry').hidden=false;render(true);}finally{busy=false;drainUpdates();}}
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');try{a.href=url;a.download=name;a.click();}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}}
async function exportProgress(){download(envelope(await store.get()),'dq3-progress-'+new Date().toISOString().slice(0,10)+'.json');message('已開始下載備份，請確認檔案保存。');}
const safely=fn=>async e=>{try{await fn(e);}catch(error){message(error.message);}};
document.addEventListener('click',safely(async e=>{
 const route=e.target.closest('[data-view],[data-route]');if(route){e.preventDefault();const u=new URL(route.href);navigate(u.searchParams.get('view')||'roadmap',Object.fromEntries([...u.searchParams].filter(([k])=>k!=='view')));return;}
 const el=e.target.closest('button');if(!el)return;
 if(el.hasAttribute('data-reset')){reset();render();return;}
 if(el.dataset.phase){navigate('roadmap',{phase:el.dataset.phase});return;}
 if(el.dataset.category){category=el.dataset.category;reset();render();return;}
 if(el.dataset.peek){peeks.has(el.dataset.peek)?peeks.delete(el.dataset.peek):peeks.add(el.dataset.peek);render(true);return;}
 if(el.dataset.saveCounter){const id=el.dataset.saveCounter,value=Number($('counter-'+id).value);if(!Number.isSafeInteger(value)||value<0)throw Error('請輸入非負整數');await save('counters',id,{value});return;}
 if(el.dataset.saveSupply){const id=el.dataset.saveSupply,quantity=Number($('quantity-'+id).value);if(!Number.isSafeInteger(quantity)||quantity<0)throw Error('請輸入非負整數');await save('supplies',id,{quantity,done:isDone(progress,'supplies',id)});return;}
 if(el.id==='continue'){const n=nextStep(progress,data);navigate(n?'roadmap':'collections',n?{phase:n.phaseId,target:n.id}:{category:'mm'});}
 if(el.id==='save-bookmark'){const value=phase();await save('settings','phase',{value});}
 if(['export','export-progress'].includes(el.id))await exportProgress();
 if(el.id==='export-all')download(await store.exportAll(),'dq3-recovery.json');
 if(el.id==='undo'&&lastUndo){busy=true;try{progress=await undoEdit(store,lastUndo);lastUndo=null;el.hidden=true;message('已撤銷該筆，其他紀錄保留。');render(true);}finally{busy=false;drainUpdates();}}
 if(el.id==='retry'&&retry)await retry();
}));
document.addEventListener('change',safely(async e=>{const el=e.target;if(el.dataset.group){const value={done:el.checked};if(el.dataset.group==='supplies')value.quantity=progress.supplies[el.dataset.id]?.quantity||0;await save(el.dataset.group,el.dataset.id,value);return;}
 if(el.id==='phase-select'){navigate('roadmap',{phase:el.value});return;}if(el.id==='reading-unit'){navigate('roadmap',{phase:phase(),unit:el.value});return;}if(el.id==='category-select'){category=el.value;reset();render();return;}if(el.id==='status')status=el.value;if(el.id==='region')region=el.value;if(el.id==='vocation')vocation=el.value;if(el.id==='trophy-type')trophyType=el.value;if(['status','region','vocation','trophy-type'].includes(el.id))render(true);
 if(el.id==='import-file'&&el.files[0])await preview(el.files[0]);
}));
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;render(true);}});
window.addEventListener('popstate',()=>{reset();category=Object.hasOwn(cats,params().get('category'))?params().get('category'):'mm';target=params().get('target')||'';if(target)status='all';render();});
async function preview(file){
 if(file.size>10*1024*1024)throw Error('檔案超過 10 MB，停止匯入。');const sourceRaw=await file.text(),local=await store.raw(),localRaw=JSON.stringify(local);
 await store.archive({sourceRaw,localRaw,at:new Date().toISOString(),name:file.name});
 const incoming=importData(JSON.parse(sourceRaw));review={sourceRaw,localRaw,stamp:localRaw,rows:differences(local,incoming),downloaded:false,expired:false};
 $('diff-rows').innerHTML=review.rows.map((r,i)=>`<div class="diff-row"><label class="check"><input type="checkbox" data-diff="${i}" ${r.missing?'disabled':''}><span>${esc(r.group+' / '+r.id)}${r.missing?' · 來源缺少，保留本機':r.older?' · 來源較舊，需額外核對':''}</span></label><pre>本機：${esc(JSON.stringify(r.local)??'無紀錄')}\n來源：${esc(JSON.stringify(r.incoming)??'無紀錄')}</pre></div>`).join('')||'<p>兩端紀錄相同。</p>';
 $('import-status').textContent=review.rows.length+' 筆差異，未勾選項目保留本機。';$('import-ack').checked=false;$('import-ack').disabled=true;$('older-ack').checked=false;gate();$('import-dialog').showModal();
}
function gate(){$('import-apply').disabled=!review||review.expired||!review.downloaded||!$('import-ack').checked;}
$('choose-source').onclick=()=>document.querySelectorAll('[data-diff]:not(:disabled)').forEach(x=>x.checked=true);
$('choose-local').onclick=()=>document.querySelectorAll('[data-diff]').forEach(x=>x.checked=false);
$('download-recovery').onclick=async()=>{try{if(review.expired)throw Error('預覽已過期');download({gameId,recoveryBundle:{localRaw:review.localRaw,sourceRaw:review.sourceRaw},progress:JSON.parse(review.localRaw)},'dq3-before-import.json');review.downloaded=true;$('import-ack').disabled=false;$('import-status').textContent='備份已開始下載，請確認檔案保存後勾選。';}catch(e){review.downloaded=false;$('import-ack').checked=false;$('import-ack').disabled=true;$('import-status').textContent='備份失敗：'+e.message;}gate();};
$('import-ack').onchange=gate;
$('import-apply').onclick=async()=>{if(!review||$('import-apply').disabled)return;const selected=new Set([...document.querySelectorAll('[data-diff]:checked')].map(el=>{const r=review.rows[Number(el.dataset.diff)];return r.group+'/'+r.id;}));busy=true;try{await store.checkpoint('匯入前');progress=await store.update(p=>applyDifferences(p,review.rows,selected,$('older-ack').checked),review.stamp);lastUndo=null;$('undo').hidden=true;review=null;$('import-dialog').close();message('已套用選定差異，原文與快照均保留。');render(true);}catch(e){$('import-status').textContent=e.message;if(e.message.includes('過期'))review.expired=true;gate();}finally{busy=false;drainUpdates();}};
$('import-close').onclick=()=>{$('import-dialog').close();review=null;};
$('import-dialog').addEventListener('close',()=>{review=null;$('import-file')?.focus();});
try{const response=await fetch('./data.json');if(!response.ok)throw Error('攻略資料讀取失敗（'+response.status+'）');data=await response.json();if(data.gameId!==gameId||data.steps?.length!==38||data.trophies?.length!==42||data.collectibles?.length!==394||data.skills?.length!==135)throw Error('攻略資料不完整，請重新載入');progress=await store.open();ready=true;reset();category=Object.hasOwn(cats,params().get('category'))?params().get('category'):'mm';target=params().get('target')||'';if(target)status='all';$('menu').open=matchMedia('(min-width:721px)').matches;render();message('進度已載入，操作會保存於此瀏覽器。');if(target)requestAnimationFrame(()=>$('entry-'+target)?.scrollIntoView());if(params().get('section'))requestAnimationFrame(()=>$(params().get('section'))?.scrollIntoView());}
catch(e){$('main').innerHTML='<h1>無法載入</h1><p>'+esc(e.message)+'</p><p>原有紀錄未歸零。可重新載入，或先下載資料庫原文再排查。</p><button id="reload">重新載入</button><button id="raw-export">下載原始封存</button>';$('reload').onclick=()=>location.reload();$('raw-export').onclick=safely(async()=>download(await store.exportAll(),'dq3-unreadable-original.json'));message('載入失敗，已停止進度寫入。');}
